import { mkdir, readFile, writeFile } from 'node:fs/promises';
import { fileURLToPath } from 'node:url';
import path from 'node:path';
import { format, resolveConfig } from 'prettier';
import { shadcnComponentPresets } from '../../packages/prototypes/shadcn/src/component-presets.ts';

const root = path.resolve(path.dirname(fileURLToPath(import.meta.url)), '../..');
const outputPath = path.join(
  root,
  'packages/cli/src/registry/shadcn-component-presets.generated.ts'
);
const check = process.argv.includes('--check');
const rawContent = [
  '/* This file is generated by scripts/components/generate-shadcn-component-presets.mjs. */',
  '/* Edit packages/prototypes/shadcn/src/component-presets.ts instead. */',
  '',
  `export const SHADCN_COMPONENT_PRESET_RECIPES = ${JSON.stringify(
    shadcnComponentPresets,
    null,
    2
  )} as const;`,
  '',
].join('\n');
const prettierConfig = (await resolveConfig(outputPath)) ?? {};
const content = await format(rawContent, {
  ...prettierConfig,
  filepath: outputPath,
});

if (check) {
  const current = await readFile(outputPath, 'utf8').catch(() => '');
  if (current !== content) {
    console.error(
      '[component-presets] generated CLI projection is stale; run component-presets:generate'
    );
    process.exitCode = 1;
  } else {
    console.log('[component-presets] generated CLI projection is current');
  }
} else {
  await mkdir(path.dirname(outputPath), { recursive: true });
  await writeFile(outputPath, content);
  console.log(
    `[component-presets] wrote ${path.relative(root, outputPath)} (${Object.keys(shadcnComponentPresets).length} recipes)`
  );
}
